package vn.svframe.svframelib.api.crafting.recipes.vmp; import vn.svframe.svframelib.api.crafting.recipes.SVFrameRecipeStation; import java.util.*; public class CraftingMapping extends VanillaInventoryMapping { public int getMainWidth(int r){return 2;} public int getMainHeight(int c){return 2;} public int getMainSlot(int x,int y){if(x<0||x>=2||y<0||y>=2)throw outOfBounds(x,y);return 1+y*2+x;} public int getMainInventoryStart(){return 1;} public int getMainInventoryWidth(){return 2;} public int getMainInventoryHeight(){return 2;} public int getResultWidth(int r){return 1;} public int getResultHeight(int c){return 1;} public int getResultSlot(int x,int y){if(x!=0||y!=0)throw outOfBounds(x,y);return 0;} public int getResultInventoryStart(){return 0;} public int getResultInventoryWidth(){return 1;} public int getResultInventoryHeight(){return 1;} public boolean isResultSlot(int s){return s==0;} public int getSideWidth(String n,int r){throw sideInventoryException(n);} public int getSideHeight(String n,int c){throw sideInventoryException(n);} public int getSideSlot(String n,int x,int y){throw sideInventoryException(n);} public int getSideInventoryStart(String n){throw sideInventoryException(n);} public int getSideInventoryWidth(String n){throw sideInventoryException(n);} public int getSideInventoryHeight(String n){throw sideInventoryException(n);} public boolean mainIsResult(){return false;} public SVFrameRecipeStation getIntendedStation(){return SVFrameRecipeStation.WORKBENCH;} public String getIntendedInventory(){return "CRAFTING";} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>();} }
